package seating

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The M3 contract of the venue SVG generator (apps/venue-svg-generator): the
// authoring SVG its `arena_export` package writes must pass ImportSVG with the
// identity and the position of every seat intact. The SVG and the expectation
// next to it are generated by that package's pytest from a SYNTHETIC workbook
// (no client data) and committed; regenerate them with
// VENUE_GEN_REGEN_FIXTURE=1 python -m pytest arena_export  (inside the generator folder).

type venueGenExpected struct {
	Canvas struct {
		Width  float64 `json:"width"`
		Height float64 `json:"height"`
	} `json:"canvas"`
	Category struct {
		Name  string `json:"name"`
		Color string `json:"color"`
	} `json:"category"`
	SeatRadius float64 `json:"seat_radius"`
	Seats      []struct {
		Section string  `json:"section"`
		Row     string  `json:"row"`
		Number  string  `json:"number"`
		X       float64 `json:"x"`
		Y       float64 `json:"y"`
	} `json:"seats"`
}

func venueGenFixtureDir() string {
	return filepath.Join("..", "..", "..", "..", "venue-svg-generator", "arena_export", "testdata")
}

func TestImportSVG_VenueGeneratorAuthoringExport(t *testing.T) {
	t.Parallel()
	dir := venueGenFixtureDir()
	raw, err := os.ReadFile(filepath.Join(dir, "synthetic_authoring.svg"))
	if err != nil {
		t.Fatalf("read generated SVG: %v", err)
	}
	expRaw, err := os.ReadFile(filepath.Join(dir, "synthetic_authoring.expected.json"))
	if err != nil {
		t.Fatalf("read expectation: %v", err)
	}
	var exp venueGenExpected
	if err := json.Unmarshal(expRaw, &exp); err != nil {
		t.Fatalf("decode expectation: %v", err)
	}
	if len(exp.Seats) == 0 {
		t.Fatal("expectation lists no seats")
	}

	geo, warnings, errs := ImportSVG(raw)
	if len(errs) != 0 {
		t.Fatalf("ImportSVG errors: %+v", errs)
	}
	if len(warnings) != 0 {
		t.Fatalf("ImportSVG warnings: %+v", warnings)
	}

	if geo.Canvas.Width != exp.Canvas.Width || geo.Canvas.Height != exp.Canvas.Height {
		t.Errorf("canvas = %gx%g, want %gx%g", geo.Canvas.Width, geo.Canvas.Height, exp.Canvas.Width, exp.Canvas.Height)
	}

	// Exactly one category: the temporary placeholder, no commercial data.
	if len(geo.Categories) != 1 {
		t.Fatalf("categories = %d, want 1: %+v", len(geo.Categories), geo.Categories)
	}
	cat := geo.Categories[0]
	if cat.Name != exp.Category.Name || !strings.EqualFold(cat.Color, exp.Category.Color) {
		t.Errorf("category = %q %q, want %q %q", cat.Name, cat.Color, exp.Category.Name, exp.Category.Color)
	}
	if cat.IsGA() || cat.PriceHint != "" {
		t.Errorf("placeholder category must be a plain seated one without a price hint: %+v", cat)
	}

	// Every seat: identity (sector|row|number) and position, one category.
	type got struct {
		x, y, r  float64
		category int
	}
	byKey := map[string]got{}
	for _, sec := range geo.Sections {
		for _, row := range sec.Rows {
			for _, seat := range row.Seats {
				if _, dup := byKey[seat.Key]; dup {
					t.Fatalf("duplicate seat key %q", seat.Key)
				}
				byKey[seat.Key] = got{seat.X, seat.Y, seat.Radius, seat.CategoryIndex}
			}
		}
	}
	if len(byKey) != len(exp.Seats) {
		t.Fatalf("seats = %d, want %d", len(byKey), len(exp.Seats))
	}
	for _, want := range exp.Seats {
		key := SeatKey(normalizeKey(want.Section), normalizeKey(want.Row), want.Number)
		g, ok := byKey[key]
		if !ok {
			t.Errorf("seat %q missing from the imported geometry", key)
			continue
		}
		if g.x != want.X || g.y != want.Y {
			t.Errorf("seat %q at (%g,%g), want (%g,%g)", key, g.x, g.y, want.X, want.Y)
		}
		if g.r != exp.SeatRadius {
			t.Errorf("seat %q radius %g, want %g", key, g.r, exp.SeatRadius)
		}
		if g.category != cat.Index {
			t.Errorf("seat %q category %d, want %d", key, g.category, cat.Index)
		}
	}
}
